+'use strict';
+
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const { parseConfig } = require('./config.cjs');
+
+test('exports parseConfig and applies defaults', () => {
+  assert.deepEqual(parseConfig('{}'), {
+    port: 3000,
+    host: '127.0.0.1',
+    retries: 2,
+    logLevel: 'info',
+  });
+});
+
+test('accepts a complete valid configuration and returns a fresh object', () => {
+  const config = parseConfig('{"port":65535,"host":"example.test","retries":0,"logLevel":"debug"}');
+  assert.deepEqual(config, { port: 65535, host: 'example.test', retries: 0, logLevel: 'debug' });
+  assert.notStrictEqual(config, parseConfig('{}'));
+});
+
+test('rejects malformed input, non-objects, unknown keys, and explicit nulls', () => {
+  for (const input of [42, null, undefined, '[{}]', 'null', '[]', '{', '{"extra":true}', '{"port":null}']) {
+    assert.throws(() => parseConfig(input), Error);
+  }
+});
+
+test('rejects invalid port and retry values without coercion', () => {
+  for (const input of [
+    '{"port":0}', '{"port":65536}', '{"port":1.5}', '{"port":"3000"}',
+    '{"retries":-1}', '{"retries":11}', '{"retries":1.5}', '{"retries":"2"}',
+  ]) {
+    assert.throws(() => parseConfig(input), Error);
+  }
+});
+
+test('rejects invalid hosts and log levels', () => {
+  for (const input of [
+    '{"host":""}', '{"host":"has space"}', '{"host":"has\\nnewline"}',
+    `{"host":"${'a'.repeat(254)}"}`, '{"host":123}', '{"logLevel":"trace"}',
+    '{"logLevel":null}',
+  ]) {
+    assert.throws(() => parseConfig(input), Error);
+  }
+});
+
+test('does not share mutable result state between calls', () => {
+  const first = parseConfig('{}');
+  first.port = 1234;
+  assert.equal(parseConfig('{}').port, 3000);
+});

