+function request(server, method, pathname, value) {
+  return new Promise((resolve, reject) => {
+    const req = http.request({ port: server.address().port, host: '127.0.0.1', method, path: pathname, headers: value === undefined ? {} : { 'content-type': 'application/json' } }, res => {
+      const chunks = [];
+      res.on('data', chunk => chunks.push(chunk));
+      res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(chunks).toString() }));
+    });
+    req.on('error', reject);
+    if (value !== undefined) req.end(JSON.stringify(value)); else req.end();
+  });
+}
+
+async function withServer(fn, options = {}) {
+  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'rest-items-'));
+  const file = path.join(dir, 'nested', 'items.json');
+  const server = createServer({ file, ...options });
+  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
+  try { return await fn(server, file); } finally { await new Promise(resolve => server.close(resolve)); fs.rmSync(dir, { recursive: true, force: true }); }
+}
